    out = [row[:] for row in grid]

    # Detect solid monochrome rectangles, keeping only maximal rectangles
    # for each color and recoloring the full rectangle.
    for color in range(10):
        for top in range(h):
            common = [grid[top][c] == color for c in range(w)]
            for bottom in range(top, h):
                if bottom > top:
                    common = [common[c] and grid[bottom][c] == color
                              for c in range(w)]
                if bottom - top + 1 < 5:
                    continue
                c = 0
                while c < w:
                    if not common[c]:
                        c += 1
                        continue
                    left = c
                    while c < w and common[c]:
                        c += 1
                    if c - left < 5:
                        continue

                    # Skip if this rectangle can be extended vertically
                    # while preserving the same solid rectangle.
                    can_extend_up = top > 0 and all(
                        grid[top - 1][j] == color for j in range(left, c)
                    )
                    can_extend_down = bottom + 1 < h and all(
                        grid[bottom + 1][j] == color for j in range(left, c)
                    )
                    if can_extend_up or can_extend_down:
                        continue

                    for r in range(top, bottom + 1):
                        for j in range(left, c):
                            out[r][j] = 4
    return out
